#!/usr/bin/env python3
"""scene_harness.py — compose a scene from isolated clip files and render clip-level outputs.

Clip isolation by construction:
  scenes/s03/clips/clip_01.py   defines exactly `def clip_01(self): ...`
  scenes/s03/clips/clip_02.py   defines exactly `def clip_02(self): ...`
  scenes/s03/scene.py           GENERATED here — never edited by an LLM

The clip agent for s03c02 may only write clips/clip_02.py, so it cannot break clip_01 or clip_03.
Continuity objects are passed through `self.reg` (names = continuity contract).

Rendering uses Manim sections (verified on 0.20.1):
  * every clip opens a section → `--save_sections` emits one MP4 per clip + a JSON with durations;
  * `--target clip_02` marks earlier sections skip_animations=True: their code still runs (exact entry
    state, no reconstruction) but no frames are rendered, so a single-clip draft is fast;
  * clips after the target are not executed at all (T2S_STOP_AFTER).

Usage:
  python tools/scene_harness.py compose scenes/s03 --scene-id s03 [--camera]
  python tools/scene_harness.py render  scenes/s03 --scene-id s03 [--target clip_02] [--quality l|m|h|k]
Status: IMPLEMENTED in this package (tests/test_scene_harness.py).
"""
from __future__ import annotations
import argparse, ast, json, os, re, shutil, subprocess, sys
from pathlib import Path

TEMPLATE = '''# GENERATED by tools/scene_harness.py — do not edit. Edit clips/clip_NN.py instead.
import os
from manim import *
{imports}

_TARGET = os.environ.get("T2S_TARGET_CLIP")      # render only this clip's frames
_STOP_AFTER = os.environ.get("T2S_STOP_AFTER")   # do not execute clips after this one


class {cls}({base}):
    CLIPS = {clips!r}

    def construct(self):
        self.reg = {{}}
        for name in self.CLIPS:
            self.next_section(name, skip_animations=bool(_TARGET) and name < _TARGET)
            getattr(self, name)()
            if _STOP_AFTER and name >= _STOP_AFTER:
                break
{binds}
'''


def class_name(scene_id: str) -> str:
    return "Scene" + scene_id[1:].zfill(2)


def check_clip_file(path: Path) -> str:
    """A clip file may contain only imports, module constants and exactly one function named like the file."""
    tree = ast.parse(path.read_text())
    funcs = [n for n in tree.body if isinstance(n, ast.FunctionDef)]
    if len(funcs) != 1 or funcs[0].name != path.stem:
        raise SystemExit(f"{path}: must define exactly one function named {path.stem}")
    for n in tree.body:
        if not isinstance(n, (ast.FunctionDef, ast.Import, ast.ImportFrom, ast.Assign, ast.Expr)):
            raise SystemExit(f"{path}: unexpected top-level statement {type(n).__name__}")
    return path.stem


def compose(scene_dir: Path, scene_id: str, camera: bool = False) -> Path:
    clips = sorted(scene_dir.glob("clips/clip_*.py"))
    if not clips:
        raise SystemExit(f"no clips in {scene_dir}/clips")
    names = [check_clip_file(p) for p in clips]
    imports = "\n".join(f"from clips.{n} import {n} as _{n}" for n in names)
    binds = "\n".join(f"    {n} = _{n}" for n in names)
    src = TEMPLATE.format(imports=imports, cls=class_name(scene_id), base="MovingCameraScene" if camera else "Scene",
                          clips=names, binds=binds)
    (scene_dir / "clips" / "__init__.py").write_text("")
    out = scene_dir / "scene.py"
    out.write_text(src)
    return out


# Quality presets (-ql/-qm/-qh) OVERRIDE pixel_width/height from manim.cfg (verified on 0.20.1: a 1080x1920
# manim.cfg rendered with -ql gives 854x480). Portrait output therefore always passes -r explicitly.
PORTRAIT_RES = {"l": "480,854", "m": "720,1280", "h": "1080,1920", "k": "2160,3840"}


def render(scene_dir: Path, scene_id: str, target: str | None, quality: str, media: str = "media",
           aspect: str = "16:9") -> dict:
    env = dict(os.environ)
    if target:
        env["T2S_TARGET_CLIP"] = target; env["T2S_STOP_AFTER"] = target
    cls = class_name(scene_id)
    cmd = [sys.executable, "-m", "manim", "render", "scene.py", cls, f"-q{quality}", "--save_sections",
           "--media_dir", media, "--disable_caching"]
    if aspect == "9:16":
        cmd += ["-r", PORTRAIT_RES[quality]]
    p = subprocess.run(cmd, cwd=scene_dir, env=env, capture_output=True, text=True, timeout=3600)
    if p.returncode != 0:
        return {"ok": False, "returncode": p.returncode, "stderr_tail": p.stderr[-3000:]}
    sec_json = next((scene_dir / media).rglob(f"sections/{cls}.json"))
    sections = json.loads(sec_json.read_text())
    for s in sections:
        s["path"] = str((sec_json.parent / s["video"]).relative_to(scene_dir))
        s["duration"] = float(s["duration"])
    return {"ok": True, "class": cls, "target": target, "quality": quality, "sections": sections}


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("action", choices=["compose", "render"])
    ap.add_argument("scene_dir", type=Path)
    ap.add_argument("--scene-id", required=True)
    ap.add_argument("--camera", action="store_true")
    ap.add_argument("--target")
    ap.add_argument("--quality", default="l", choices=list("lmhk"))
    ap.add_argument("--aspect", default="16:9", choices=["16:9", "9:16"])
    a = ap.parse_args()
    if a.action == "compose":
        print(compose(a.scene_dir, a.scene_id, a.camera))
    else:
        r = render(a.scene_dir, a.scene_id, a.target, a.quality, aspect=a.aspect)
        print(json.dumps(r, indent=1))
        sys.exit(0 if r["ok"] else 1)


if __name__ == "__main__":
    main()
